"""Build a self-contained offline viewer from exported CAD meshes."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
OUT=HERE/'output'

def run():
    data=json.loads((OUT/'meshes.json').read_text(encoding='utf-8'))
    js=(HERE/'viewer.js').read_text(encoding='utf-8').replace('__DATA__',json.dumps(data,separators=(',',':')))
